const WORKPACE = '4trb';
const data = [];
/** @type {{[key: string]: any}} */
const uniqueMap = {};

for (const item of $input.all()) {
  const key = item['json']['location'] + '::' + item['json']['code'];
  if (!uniqueMap[key]) {
    const newItem = {
      location: item['json']['location'],
      code: item['json']['code'],
      description: item['json']['description'],
      materialType: 'finished',
      multipleOrderQuantity: item['json']['multipleOrderQuantity'],
      currency: 'USD',
      unitCost: item['json']['unitCost'],
      minimumOrderQuantity: 1,
      unitOfMeasure: 'units',
      supplyLeadTime: item['json']['supplyLeadTime'],
      onHandStock: item['json']['onHandStock'],
      transitStock: item['json']['transitStock'],
      openDemandOrders: item['json']['openDemandOrders'],
      additionalColumns: [
        {
          name: 'supplierName',
          content: item['json']['SuppName'],
        },
        {
          name: 'supplierCode',
          content: item['json']['CardCode'],
        },
        {
          name: 'nationalUioDays',
          content: item['json']['nationalUioDays'],
        },
        {
          name: 'nationalGyeDays',
          content: item['json']['nationalGyeDays'],
        },
        {
          name: 'transitDays',
          content: item['json']['transitDays'],
        },
      ],
      workspaceCode: WORKPACE,
    };

    uniqueMap[key] = newItem;
  } else {
    uniqueMap[key].onHandStock += item['json']['onHandStock'];
    uniqueMap[key].transitStock += item['json']['transitStock'];
    uniqueMap[key].openDemandOrders += item['json']['openDemandOrders'];
  }
}

data.push(...Object.values(uniqueMap));

return {data: data}

const WORKSPACECODE  = '4trb';
function transformData(originalArray) {
    const grouped = originalArray.reduce((acc, item) => {
        const key = `${item.location}-${item.code}`;

        if (!acc[key]) {
            acc[key] = {
                location: item.location,
                code: item.code,
                items: []
            };
        }

        acc[key].items.push({
            date: item.date.split('T')[0],
            quantity: item.quantity
        });

        return acc;
    }, {});

    const result = {
        data: Object.values(grouped).map(group => {
            group.items.sort((a, b) => new Date(a.date) - new Date(b.date));

            return {
                location: group.location,
                code: group.code,
                dates: group.items.map(item => item.date),
                quantities: group.items.map(item => item.quantity),
                workspaceCode:WORKSPACECODE
            };
        })
    };

    return result;
}
const base_data = $input.all().map(i => i.json);
return transformData(base_data);
